import{_ as o,o as r,c as a,a1 as p}from"./chunks/framework.DTPhowZX.js";const d=JSON.parse('{"title":"Обо мне","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1793022327000}'),n={name:"about/index.md"};function l(e,t,i,s,u,g){return r(),a("div",null,[...t[0]||(t[0]=[p('<h1 id="обо-мне" tabindex="-1">Обо мне <a class="header-anchor" href="#обо-мне" aria-label="Permalink to &quot;Обо мне&quot;">​</a></h1><h2 id="🌟-визитная-карточка" tabindex="-1">🌟 Визитная карточка <a class="header-anchor" href="#🌟-визитная-карточка" aria-label="Permalink to &quot;🌟 Визитная карточка&quot;">​</a></h2><p>👩‍🏫 Катович Елена Владимировна</p><p>Учитель истории и обществознания</p><p>Муниципальное бюджетное общеобразовательное учреждение «СОШ № 10» села Орловки Кировского муниципального округа</p><h2 id="📊-коротко-о-главном" tabindex="-1">📊 Коротко о главном <a class="header-anchor" href="#📊-коротко-о-главном" aria-label="Permalink to &quot;📊 Коротко о главном&quot;">​</a></h2><p>Стаж педагогической деятельности: 33 года</p><p>Квалификационная категория: Высшая</p><p>Профиль: История, обществознание, право</p><h2 id="🎯-мое-педагогическое-кредо" tabindex="-1">🎯 Мое педагогическое кредо <a class="header-anchor" href="#🎯-мое-педагогическое-кредо" aria-label="Permalink to &quot;🎯 Мое педагогическое кредо&quot;">​</a></h2><p>«Учить не мыслям, а мыслить. История — это не просто даты, это живая связь поколений и учительница жизни. Моя задача — воспитать в учениках критическое мышление, гражданскую ответственность и патриотизм».</p><h2 id="💡-профессиональные-компетенции-и-опыт" tabindex="-1">💡 Профессиональные компетенции и опыт <a class="header-anchor" href="#💡-профессиональные-компетенции-и-опыт" aria-label="Permalink to &quot;💡 Профессиональные компетенции и опыт&quot;">​</a></h2><p>Современные технологии: Активно применяю технологии сотрудничества, проблемного обучения, исследовательской деятельности и уровневой дифференциации.</p><p>Результативность: Стабильно высокое качество знаний (до 78,7% по истории). Мои ученики — победители и призёры муниципальных и краевых олимпиад, а также конкурсов («Наследники Победы», «Без срока давности»).</p><p>Экспертная деятельность: Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по обществознанию и истории (г. Ставрополь).</p><p>Внеурочная работа: Руководитель историко-краеведческого музея «История села Орловки» (призёр регионального этапа Всероссийского конкурса школьных музеев).</p><h2 id="🏆-ключевые-достижения" tabindex="-1">🏆 Ключевые достижения <a class="header-anchor" href="#🏆-ключевые-достижения" aria-label="Permalink to &quot;🏆 Ключевые достижения&quot;">​</a></h2><p>2017 г. - Почетная грамота Министерства образования Ставропольского края за значительный вклад в развитие системы образования Ставропольского края;</p><p>2022 г. – Благодарственное письмо Губернатора Ставропольского края за подготовку победителя регионального этапа всероссийской олимпиады школьников;</p><p>2023 г. — Диплом Министерства образования Ставропольского края за добросовестный труд и высокий профессионализм;</p><p>2023 г - Диплом II степени Центра организации и проведения дистанционных конкурсов для педагогов «Завуч» за авторскую разработку «Современные образовательные технологии на уроках истории»,</p><p>2024 г - Диплом I степени Центра организации и проведения дистанционных конкурсов для педагогов «Завуч» за авторскую разработку «Конституция-главный закон страны»,</p><p>2025 г - Дипломом I степени образовательный портал для проведения дистанционных конкурсов для педагогов «Завуч» за участие в конкурсе профессионального мастерства (номинация «Человек в истории. Россия – XX век»,</p><p>2025 г - Благодарность Русской Православной церкви Пятигорской и Черкеской епархии за активное участие в работе секции отдела по миссионерскому служению епархии в рамках подготовительных мероприятий к XXXIII Международным Рождественским образовательным чтениям и XII Рождественским епархиальным образовательным чтениям на тему: «80-летие Великой Победы: память и духовный опыт поколений»,</p><p>2024 г. — Нагрудный знак «Почетный работник сферы образования Российской Федерации».</p><p>2026 г. — Победитель конкурса лучших учителей образовательных организаций для денежного поощрения за высокие достижения в педагогической деятельности.</p><p>2026 г. — Благодарственное письмо Губернатора Ставропольского края за вклад в развитие системы образования в крае.</p><h2 id="📬-контакты-для-связи" tabindex="-1">📬 Контакты для связи <a class="header-anchor" href="#📬-контакты-для-связи" aria-label="Permalink to &quot;📬 Контакты для связи&quot;">​</a></h2><p>Место работы: МБОУ СОШ № 10 с. Орловки</p><p>Личная страница:</p><p>Электронная почта : <a href="mailto:e.katovitch@yandex.ru" target="_blank" rel="noreferrer">e.katovitch@yandex.ru</a></p><p>Режим работы: 9.00-17.00</p><h2 id="образование-и-повышение-квалификации" tabindex="-1">Образование и повышение квалификации <a class="header-anchor" href="#образование-и-повышение-квалификации" aria-label="Permalink to &quot;Образование и повышение квалификации&quot;">​</a></h2><p><strong>Образование</strong></p><p><strong>Высшее профессиональное</strong></p><ul><li><p><strong>Учебное заведение:</strong> Ставропольский государственный педагогический институт</p></li><li><p><strong>Год окончания:</strong> 1992</p></li><li><p><strong>Специальность:</strong> История, социально-политические дисциплины</p></li><li><p><strong>Квалификация:</strong> Учитель истории и социально-политических дисциплин</p></li></ul><p><strong>🎓 Повышение квалификации (2023–2026 гг.)</strong></p><p><strong>2026 год</strong></p><ul><li><p><strong>«Преподавание истории в основной школе по единым учебникам»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (27.03.2026 – 17.04.2026).</p></li><li><p><strong>«Преподавание курса &quot;История нашего края&quot; в 5-7 классах»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (02.02.2026 – 04.02.2026).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам основного общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (02.02.2026 – 04.02.2026).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам среднего общего образования по предмету &quot;История&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (19.01.2026 – 21.01.2026).</p></li></ul><p><strong>2025 год</strong></p><ul><li><p><strong>«Профилактика детского дорожно-транспортного травматизма как направление воспитательной работы педагога»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (09.04.2025 – 22.04.2025).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам среднего общего образования по предмету &quot;История&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (27.01.2025 – 29.01.2025).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам среднего общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (08.12.2025 – 10.12.2025).</p></li></ul><p><strong>2024 год</strong></p><ul><li><p><strong>«Классный руководитель: современная модель воспитательной деятельности»</strong> — ООО «ЦДО СПТ» (23.10.2024 – 30.10.2024).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам основного общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (16.10.2024 – 18.10.2024).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам среднего общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (06.11.2024 – 08.11.2024).</p></li></ul><p><strong>2023 год</strong></p><ul><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам основного общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (16.10.2023 – 18.10.2023).</p></li><li><p><strong>«Актуальные вопросы обучения истории и обществознанию в условиях реализации ФГОС»</strong> — ООО «ЦДО СПТ» (06.10.2023 – 13.10.2023).</p></li><li><p><strong>«Специфика реализации новых ФООП и базовые компетенции учителя в современной школе»</strong> — ООО «ФРО» (22.07.2023).</p></li><li><p><strong>«Школа современного учителя истории и обществознания: достижения российской науки»</strong> — ФГАОУ ДПО «Академия реализации государственной политики и профессионального развития работников образования Министерства просвещения РФ» (01.03.2023 – 24.04.2023).</p></li><li><p><strong>«Подготовка экспертов для работы в региональной предметной комиссии при проведении ГИА по образовательным программам среднего общего образования по предмету &quot;Обществознание&quot;»</strong> — ГБУ ДПО «СКИРО ПК и ПРО» (22.11.2023 – 24.11.2023).</p></li></ul><p><strong>Скачать:</strong></p><ul><li><a href="/teacher/files/about/Визитная карточка.docx">Визитная карточка (DOCX)</a></li><li><a href="/teacher/files/about/Образование и повышение квалификации.docx">Образование (DOCX)</a></li></ul>',47)])])}const c=o(n,[["render",l]]);export{d as __pageData,c as default};
